// Copies the repository's canonical licence/notice files into public/legal/
// so Vite includes them verbatim in dist/ (Vite copies everything under its
// public directory into the build output root, unchanged). This keeps the
// top-level LICENSE and LICENSES/THIRD-PARTY-NOTICES.md as the one
// canonical source of truth - the in-app About screen links to these
// copies rather than duplicating their text, so there is nothing to keep
// hand-in-sync or let drift.
//
// public/legal/ is gitignored (see .gitignore) and regenerated by this
// script on every `npm run dev`/`npm run build`, so it is always an exact,
// fresh copy of the real files, never a second, independently-edited copy.

import { copyFileSync, mkdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const repoRoot = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const legalDir = path.join(repoRoot, 'public', 'legal');

mkdirSync(legalDir, { recursive: true });

copyFileSync(path.join(repoRoot, 'LICENSE'), path.join(legalDir, 'LICENSE.txt'));
copyFileSync(
  path.join(repoRoot, 'LICENSES', 'THIRD-PARTY-NOTICES.md'),
  path.join(legalDir, 'THIRD-PARTY-NOTICES.md'),
);
